// ===== TỒN KHO =====
const DEFAULT_STOCK = {
  1:80, 2:120, 3:65, 4:45, 5:200, 6:30, 7:150, 8:90,
  9:55, 10:180, 11:70, 12:40, 13:25, 14:60, 15:35, 16:50,
  17:20, 18:30, 19:8, 20:75, 21:15, 22:12, 23:40, 24:18,
  25:300, 26:110, 27:22, 28:500, 29:85, 30:95, 31:45, 32:160,
};
const STOCK_STORE_KEY = 'tpx_stock_v1';
function loadAllStock() { try { return JSON.parse(localStorage.getItem(STOCK_STORE_KEY)) || {}; } catch(e) { return {}; } }
function saveAllStock(m) { localStorage.setItem(STOCK_STORE_KEY, JSON.stringify(m)); }
function getStock(id) { const m=loadAllStock(), n=Number(id); return typeof m[n]!=='undefined'?Number(m[n]):(DEFAULT_STOCK[n]??0); }
function getStockStatus(id) { const q=getStock(id); return q<=0?'out':q<=10?'low':'ok'; }
function adminAdjustStock(productId, delta) { adminSetStock(productId, getStock(productId)+delta); }
function initStockDefaults() {
  const m=loadAllStock(); let changed=false;
  PRODUCTS.forEach(p=>{ if(typeof m[p.id]==='undefined'){m[p.id]=DEFAULT_STOCK[p.id]??0; changed=true;} });
  if(changed) saveAllStock(m);
}

// ===== ĐỒNG BỘ THỜI GIAN THỰC =====
const TPX_SYNC_CHANNEL = 'tpx_sync';
if (!window.tpxChannel) {
  window.tpxChannel = ('BroadcastChannel' in window)
    ? (function(){ try{ return new BroadcastChannel(TPX_SYNC_CHANNEL); }catch(e){ return null; } })()
    : null;
}
if (!window.tpxTabId) window.tpxTabId = 'tab-'+Math.random().toString(36).slice(2);

function tpxBroadcast(type, payload) {
  const msg={type,payload:payload||{},ts:Date.now(),from:window.tpxTabId};
  if(window.tpxChannel){ try{ window.tpxChannel.postMessage(msg); }catch(e){} }
  try{ localStorage.setItem('tpx_sync_ping',JSON.stringify(msg)); }catch(e){}
}
function tpxHandleSyncMessage(msg) {
  if(!msg||!msg.type||msg.from===window.tpxTabId) return;
  switch(msg.type){
    case 'stock':
      if(typeof renderProducts==='function') renderProducts();
      if(typeof renderFlashSale==='function') renderFlashSale();
      if(isAdminLoggedIn&&typeof renderStockManager==='function') renderStockManager();
      tpxSyncToast('Tồn kho vừa được cập nhật'); break;
    case 'image':
      if(typeof renderProducts==='function') renderProducts();
      if(typeof renderFlashSale==='function') renderFlashSale();
      if(isAdminLoggedIn){ if(typeof renderProductImageManager==='function') renderProductImageManager(); if(typeof renderImageManager==='function') renderImageManager(); if(typeof renderStockManager==='function') renderStockManager(); }
      if(typeof applyStoredImages==='function') applyStoredImages();
      if(typeof renderCartItems==='function') renderCartItems();
      if(!isAdminLoggedIn) tpxSyncToast('Ảnh sản phẩm vừa được cập nhật'); break;
    case 'admin_avatar':
      if(typeof applyAdminAvatar==='function') applyAdminAvatar(); break;
    case 'orders':
      orders=JSON.parse(localStorage.getItem('orders')||'[]');
      if(isAdminLoggedIn&&typeof loadAdminData==='function') loadAdminData();
      if(msg.payload&&msg.payload.notifyCustomer&&currentUser&&msg.payload.userId===currentUser.email)
        showToast(msg.payload.message||'Đơn hàng của bạn vừa được cập nhật','green'); break;
    case 'users':
      users=JSON.parse(localStorage.getItem('users')||'[]');
      if(isAdminLoggedIn&&typeof renderUsersTable==='function') renderUsersTable(); break;
  }
}
if(window.tpxChannel){ window.tpxChannel.onmessage=function(e){ tpxHandleSyncMessage(e.data); }; }
window.addEventListener('storage',function(e){
  if(e.key==='tpx_sync_ping'&&e.newValue){ try{ tpxHandleSyncMessage(JSON.parse(e.newValue)); }catch(err){} }
  if(e.key==='customProductImages'){
    if(typeof renderProducts==='function') renderProducts();
    if(typeof renderFlashSale==='function') renderFlashSale();
    if(typeof applyStoredImages==='function') applyStoredImages();
    if(typeof renderCartItems==='function') renderCartItems();
    if(isAdminLoggedIn){ if(typeof renderProductImageManager==='function') renderProductImageManager(); if(typeof renderImageManager==='function') renderImageManager(); if(typeof renderStockManager==='function') renderStockManager(); }
  }
});
let _tpxSyncToastTimer=null;
function tpxSyncToast(msg){ if(isAdminLoggedIn) return; if(_tpxSyncToastTimer) return; showToast(msg,''); _tpxSyncToastTimer=setTimeout(()=>{ _tpxSyncToastTimer=null; },4000); }

// ===== STATE =====
let cart        = JSON.parse(localStorage.getItem('cart')   ||'[]');
let users       = JSON.parse(localStorage.getItem('users')  ||'[]');
let orders      = JSON.parse(localStorage.getItem('orders') ||'[]');
let currentUser = JSON.parse(sessionStorage.getItem('currentUser')||'null');
let currentCategory='all', currentSearch='', isAdminLoggedIn=false;

// ===== IMAGE HELPERS =====
function loadCustomImages(){ try{ return JSON.parse(localStorage.getItem('customProductImages')||'{}'); }catch{ return {}; } }
function saveCustomImages(obj){ localStorage.setItem('customProductImages',JSON.stringify(obj)); }
function getProductImage(id){ const c=loadCustomImages(); return c[id]||DEFAULT_PRODUCT_IMAGES[id]||''; }
function handleProductImageUpload(id,file){
  if(!isAdminLoggedIn){ showToast('Chỉ admin mới có thể đổi ảnh!','red'); return; }
  if(!file||!file.type.startsWith('image/')){ showToast('Vui lòng chọn file ảnh hợp lệ','red'); return; }
  if(file.size>2*1024*1024){ showToast('Ảnh quá lớn, vui lòng chọn ảnh dưới 2MB','red'); return; }
  const reader=new FileReader();
  reader.onload=(e)=>{ const c=loadCustomImages(); c[id]=e.target.result; saveCustomImages(c); if(window.products){ const wp=window.products.find(p=>p.id===id); if(wp) wp.image=e.target.result; } renderProducts(); renderFlashSale(); renderProductImageManager(); renderCartItems(); if(typeof renderStockManager==='function') renderStockManager(); tpxBroadcast('image',{id}); showToast('Cập nhật ảnh thành công!','green'); };
  reader.readAsDataURL(file);
}
function resetProductImage(id){
  if(!isAdminLoggedIn) return;
  const c=loadCustomImages(); delete c[id]; saveCustomImages(c);
  if(window.products){ const wp=window.products.find(p=>p.id===id); if(wp) wp.image=DEFAULT_PRODUCT_IMAGES[id]||''; }
  renderProducts(); renderFlashSale(); renderProductImageManager(); renderCartItems();
  if(typeof renderStockManager==='function') renderStockManager();
  tpxBroadcast('image',{id}); showToast('Đã khôi phục ảnh mặc định','');
}

// ===== INIT =====
document.addEventListener('DOMContentLoaded',()=>{
  initStockDefaults();
  window.products=PRODUCTS.map(p=>({...p,image:getProductImage(p.id)}));
  renderProducts(); renderFlashSale(); updateCartUI(); startCountdown(); updateAuthUI(); initSocialLoginModal();
});

// ===== SMOOTH SCROLL =====
const SCROLL_DURATION=800;
function smoothScrollTo(target,duration){
  const startY=window.scrollY, endY=target.getBoundingClientRect().top+window.scrollY-80, diff=endY-startY; let startTime=null;
  function easeInOutCubic(t){ return t<0.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2; }
  function step(ts){ if(!startTime) startTime=ts; const el=ts-startTime, pr=Math.min(el/duration,1); window.scrollTo(0,startY+diff*easeInOutCubic(pr)); if(pr<1) requestAnimationFrame(step); }
  requestAnimationFrame(step);
}

// ===== PRODUCTS =====
function getFilteredProducts(){
  let list=PRODUCTS;
  if(currentCategory!=='all') list=list.filter(p=>p.category===currentCategory);
  if(currentSearch) list=list.filter(p=>p.name.toLowerCase().includes(currentSearch.toLowerCase()));
  const sort=document.getElementById('sortSelect')?document.getElementById('sortSelect').value:'';
  if(sort==='price-asc') list=[...list].sort((a,b)=>a.price-b.price);
  else if(sort==='price-desc') list=[...list].sort((a,b)=>b.price-a.price);
  else if(sort==='name') list=[...list].sort((a,b)=>a.name.localeCompare(b.name));
  return list;
}
function renderProducts(){
  const grid=document.getElementById('productsGrid'), noResults=document.getElementById('noResults');
  if(!grid) return;
  const list=getFilteredProducts();
  if(!list.length){ grid.innerHTML=''; if(noResults) noResults.style.display='block'; return; }
  if(noResults) noResults.style.display='none';
  grid.innerHTML=list.map(p=>productCard(p)).join('');
}
function renderFlashSale(){
  const grid=document.getElementById('flashSaleGrid');
  if(!grid) return;
  grid.innerHTML=PRODUCTS.filter(p=>p.flashSale).slice(0,5).map(p=>productCard(p,true)).join('');
}
function productCard(p){
  const disc=p.oldPrice?Math.round((1-p.price/p.oldPrice)*100):0;
  const stars='★'.repeat(Math.floor(p.rating))+'☆'.repeat(5-Math.floor(p.rating));
  const imgSrc=getProductImage(p.id), hasCustom=!!loadCustomImages()[p.id];
  const stockQty=getStock(p.id), isOut=stockQty<=0;
  const adminImgBtn=isAdminLoggedIn?`<label class="img-upload-overlay" title="Nhấn để thay ảnh" onclick="event.stopPropagation()"><input type="file" accept="image/*" style="display:none" onchange="handleProductImageUpload(${p.id},this.files[0]);event.stopPropagation()"><span class="img-upload-icon"><i class="fas fa-camera"></i> Thay ảnh</span></label>`:'';
  const resetBtn=(isAdminLoggedIn&&hasCustom)?`<button class="btn-reset-img" onclick="resetProductImage(${p.id});event.stopPropagation()">↩ Ảnh mặc định</button>`:'';
  const soldOutOverlay=isOut?`<div class="sold-out-overlay"><span>Hết hàng</span></div>`:'';
  const stockBadge=!isAdminLoggedIn&&stockQty>0&&stockQty<=10?`<span class="stock-badge stock-low">Sắp hết: còn ${stockQty}</span>`:'';
  return `<div class="product-card" data-pid="${p.id}">${p.badge?`<span class="product-badge ${p.badge}">${p.badgeText}</span>`:''}${disc?`<span class="product-badge" style="left:auto;right:10px;background:var(--red)">-${disc}%</span>`:''}<div class="product-img-wrap"><img src="${imgSrc}" alt="${p.name}" class="product-img" loading="lazy" data-product-id="${p.id}" onerror="this.src='data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 width=%22200%22 height=%22180%22%3E%3Crect fill=%22%23f5f5f5%22 width=%22200%22 height=%22180%22/%3E%3Ctext x=%2250%25%22 y=%2250%25%22 dominant-baseline=%22middle%22 text-anchor=%22middle%22 fill=%22%23bbb%22 font-size=%2213%22%3EKhông có ảnh%3C/text%3E%3C/svg%3E'">${soldOutOverlay}${adminImgBtn}</div><div class="product-info">${stockBadge}<div class="product-rating">${stars} <span style="color:#999">(${p.sold})</span></div><div class="product-name">${p.name}</div><div class="product-origin"><span>📍 ${p.origin}</span></div><div class="product-price-row"><div class="product-prices"><span class="product-price">${formatPrice(p.price)}/${p.unit}</span>${p.oldPrice?`<span class="product-old-price">${formatPrice(p.oldPrice)}</span>`:''}</div><button class="btn-add-cart" onclick="addToCart(${p.id});event.stopPropagation()" ${isOut?'disabled style="opacity:0.4;cursor:not-allowed"':''}><i class="fas fa-cart-plus"></i></button></div>${resetBtn}</div></div>`;
}
function filterCategory(cat){
  currentCategory=cat; currentSearch='';
  const inp=document.getElementById('searchInput'); if(inp) inp.value='';
  document.querySelectorAll('.nav-list a').forEach(a=>a.classList.remove('active'));
  renderProducts();
  const sec=document.querySelector('.products-section'); if(sec) smoothScrollTo(sec,SCROLL_DURATION);
}
function searchProducts(){ const inp=document.getElementById('searchInput'); currentSearch=inp?inp.value.trim():''; currentCategory='all'; renderProducts(); }
document.addEventListener('DOMContentLoaded',()=>{ const inp=document.getElementById('searchInput'); if(inp) inp.addEventListener('keydown',e=>{ if(e.key==='Enter') searchProducts(); }); });
function sortProducts(){ renderProducts(); }

// ===== CART =====
function addToCart(id){
  const p=PRODUCTS.find(x=>x.id===id); if(!p) return;
  const stock=getStock(id); if(stock<=0){ showToast('Sản phẩm đã hết hàng!','red'); return; }
  const existing=cart.find(x=>x.id===id);
  if(existing&&existing.qty>=stock){ showToast(`Chỉ còn ${stock} sản phẩm trong kho!`,'red'); return; }
  if(existing) existing.qty++; else cart.push({id:p.id,name:p.name,price:p.price,unit:p.unit,qty:1});
  saveCart(); updateCartUI(); showToast(`Đã thêm ${p.name} vào giỏ!`,'green');
}
function updateCartUI(){
  const total=cart.reduce((s,x)=>s+x.qty,0);
  const badge=document.getElementById('cartBadge'), count=document.getElementById('cartCount');
  if(badge) badge.textContent=total; if(count) count.textContent=total;
  renderCartItems();
}
function renderCartItems(){
  const container=document.getElementById('cartItems'), footer=document.getElementById('cartFooter');
  if(!container) return;
  if(!cart.length){ container.innerHTML=`<div class="cart-empty"><span>🛒</span><p>Giỏ hàng trống</p><small>Hãy thêm sản phẩm vào giỏ</small></div>`; if(footer) footer.style.display='none'; return; }
  if(footer) footer.style.display='block';
  container.innerHTML=cart.map(item=>{ const imgSrc=getProductImage(item.id); return `<div class="cart-item"><img src="${imgSrc}" alt="${item.name}" style="width:44px;height:44px;object-fit:cover;border-radius:8px;flex-shrink:0" onerror="this.style.background='#f0f0f0'"><div class="cart-item-info"><div class="cart-item-name">${item.name}</div><div class="cart-item-price">${formatPrice(item.price*item.qty)}</div><div class="cart-item-controls"><button class="qty-btn" onclick="changeQty(${item.id},-1)">−</button><span class="qty-num">${item.qty}</span><button class="qty-btn" onclick="changeQty(${item.id},1)">+</button><button class="cart-item-delete" onclick="removeFromCart(${item.id})"><i class="fas fa-trash"></i></button></div></div></div>`; }).join('');
  const subtotal=cart.reduce((s,x)=>s+x.price*x.qty,0), ship=subtotal>=299000?0:30000;
  const elTotal=document.getElementById('cartTotal'), elShip=document.getElementById('cartShip'), elFinal=document.getElementById('cartFinal');
  if(elTotal) elTotal.textContent=formatPrice(subtotal); if(elShip) elShip.textContent=ship===0?'Miễn phí':formatPrice(ship); if(elFinal) elFinal.textContent=formatPrice(subtotal+ship);
}
function changeQty(id,delta){ const item=cart.find(x=>x.id===id); if(!item) return; if(delta>0){ const stock=getStock(id); if(item.qty>=stock){ showToast(`Chỉ còn ${stock} sản phẩm trong kho!`,'red'); return; } } item.qty+=delta; if(item.qty<=0) cart=cart.filter(x=>x.id!==id); saveCart(); updateCartUI(); }
function removeFromCart(id){ cart=cart.filter(x=>x.id!==id); saveCart(); updateCartUI(); }
function clearCart(){ cart=[]; saveCart(); updateCartUI(); }
function saveCart(){ localStorage.setItem('cart',JSON.stringify(cart)); }
function toggleCart(){ document.getElementById('cartSidebar').classList.toggle('open'); document.getElementById('cartOverlay').classList.toggle('active'); }
function checkout(){
  if(!currentUser){ toggleCart(); setTimeout(()=>showAuthModal('login'),300); showToast('Vui lòng đăng nhập để đặt hàng','red'); return; }
  if(!cart.length){ showToast('Giỏ hàng trống!','red'); return; }
  if(!currentUser.address||!currentUser.address.trim()||!currentUser.phone||!currentUser.phone.trim()){ toggleCart(); setTimeout(()=>openAddressModal(),300); showToast('Vui lòng bổ sung địa chỉ và số điện thoại nhận hàng trước khi đặt hàng','red'); return; }
  const subtotal=cart.reduce((s,x)=>s+x.price*x.qty,0), ship=subtotal>=299000?0:30000;
  const order={id:'TPX'+Date.now().toString().slice(-6),userId:currentUser.email,userName:currentUser.name,userPhone:currentUser.phone,address:currentUser.address||'',items:[...cart],subtotal,ship,total:subtotal+ship,status:'pending',time:new Date().toLocaleString('vi-VN'),timestamp:Date.now()};
  const stockMap=loadAllStock(); cart.forEach(item=>{ const id=Number(item.id); const cur=typeof stockMap[id]!=='undefined'?Number(stockMap[id]):(DEFAULT_STOCK[id]??0); stockMap[id]=Math.max(0,cur-item.qty); }); saveAllStock(stockMap);
  orders.push(order); localStorage.setItem('orders',JSON.stringify(orders));
  tpxBroadcast('stock',{bulk:true}); tpxBroadcast('orders',{isNewOrder:true,orderId:order.id});
  clearCart(); toggleCart(); renderProducts(); renderFlashSale();
  showToast(`Đặt hàng thành công! Mã đơn: ${order.id}`,'green');
  setTimeout(()=>showToast('Đơn hàng của bạn đang được xử lý','green'),3000);
}

// ===== AUTH =====
function showAuthModal(tab){ document.getElementById('authOverlay').classList.add('active'); document.getElementById('authModal').classList.add('active'); switchTab(tab); }
function closeModal(){ document.getElementById('authOverlay').classList.remove('active'); document.getElementById('authModal').classList.remove('active'); }
function switchTab(tab){ document.getElementById('loginTab').style.display=tab==='login'?'block':'none'; document.getElementById('registerTab').style.display=tab==='register'?'block':'none'; }

// ===== SOCIAL LOGIN =====
function initSocialLoginModal(){
  const overlay=document.getElementById('socialLoginOverlay'); if(!overlay) return;
  overlay.addEventListener('click',function(e){ if(e.target===this) closeSocialLogin(); });
  document.addEventListener('keydown',(e)=>{ if(e.key==='Escape'&&overlay.classList.contains('open')) closeSocialLogin(); });
}
function loginWithGoogle(){ openSocialLoginModal('google'); }
function loginWithFacebook(){ openSocialLoginModal('facebook'); }
function openSocialLoginModal(provider){
  const overlay=document.getElementById('socialLoginOverlay'), iconEl=document.getElementById('socialLoginIcon'), titleEl=document.getElementById('socialLoginTitle'), confirmBtn=document.getElementById('socialConfirmBtn');
  if(!overlay) return;
  overlay.dataset.provider=provider;
  if(provider==='google'){ iconEl.innerHTML='<i class="fab fa-google" style="color:#ea4335;font-size:32px"></i>'; titleEl.textContent='Đăng nhập với Google'; confirmBtn.className='btn-social-confirm btn-google-confirm'; confirmBtn.style.background='#ea4335'; }
  else { iconEl.innerHTML='<i class="fab fa-facebook" style="color:#1877f2;font-size:32px"></i>'; titleEl.textContent='Đăng nhập với Facebook'; confirmBtn.className='btn-social-confirm btn-facebook-confirm'; confirmBtn.style.background='#1877f2'; }
  document.getElementById('socialLoginName').value=''; document.getElementById('socialLoginEmail').value='';
  const errEl=document.getElementById('socialLoginError'); if(errEl) errEl.style.display='none';
  overlay.classList.add('open'); closeModal();
}
function closeSocialLogin(){ const overlay=document.getElementById('socialLoginOverlay'); if(overlay) overlay.classList.remove('open'); }
function confirmSocialLogin(){
  const provider=document.getElementById('socialLoginOverlay').dataset.provider, name=document.getElementById('socialLoginName').value.trim(), email=document.getElementById('socialLoginEmail').value.trim(), errEl=document.getElementById('socialLoginError');
  errEl.style.display='none';
  if(!name){ showError(errEl,'Vui lòng nhập tên hiển thị'); return; }
  if(!email||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){ showError(errEl,'Email không hợp lệ'); return; }
  const existingLocal=users.find(u=>u.email===email&&u.provider==='local'); if(existingLocal){ showError(errEl,'Email này đã đăng ký bằng tài khoản thường. Vui lòng đăng nhập bằng mật khẩu.'); return; }
  let user=users.find(u=>u.email===email&&u.provider===provider);
  if(!user){ user={id:Date.now(),name,email,phone:'',address:'',password:'',provider,createdAt:new Date().toLocaleDateString('vi-VN')}; users.push(user); localStorage.setItem('users',JSON.stringify(users)); }
  else { user.name=name; const idx=users.findIndex(u=>u.email===email&&u.provider===provider); if(idx>-1){ users[idx]=user; localStorage.setItem('users',JSON.stringify(users)); } }
  tpxBroadcast('users',{email});
  currentUser=user; sessionStorage.setItem('currentUser',JSON.stringify(user));
  updateAuthUI(); closeSocialLogin();
  showToast(`Đăng nhập ${provider==='google'?'Google':'Facebook'} thành công! Chào ${user.name} 👋`,'green');
  if(!user.address||!user.address.trim()||!user.phone||!user.phone.trim()) setTimeout(()=>openAddressModal(),400);
}
function socialLogin(provider){ openSocialLoginModal(provider); }

// ===== ADDRESS MODAL =====
function openAddressModal(){
  if(!currentUser) return;
  const ov=document.getElementById('addressModalOverlay'), inp=document.getElementById('addressInput'), phoneInp=document.getElementById('addressPhoneInput');
  if(ov) ov.classList.add('open');
  if(inp) inp.value=currentUser.address||'';
  if(phoneInp) phoneInp.value=currentUser.phone||'';
  const errEl=document.getElementById('addressError'); if(errEl){ errEl.textContent=''; errEl.style.display='none'; }
}
function closeAddressModal(){ const ov=document.getElementById('addressModalOverlay'); if(ov) ov.classList.remove('open'); }

function logout(){
  currentUser=null; sessionStorage.removeItem('currentUser'); isAdminLoggedIn=false;
  const loginSec=document.getElementById('adminLoginSection'), dashSec=document.getElementById('adminDashboard');
  if(loginSec) loginSec.style.display='block'; if(dashSec) dashSec.style.display='none';
  updateAuthUI(); renderProducts(); renderFlashSale(); showToast('Đã đăng xuất thành công','');
}
function updateAuthUI(){
  const authBtn=document.getElementById('authBtn'), authLabel=document.getElementById('authLabel');
  if(!authBtn) return;
  if(currentUser){ authLabel.textContent=currentUser.name.split(' ').pop(); authBtn.onclick=logout; authBtn.querySelector('i').className='fas fa-user-check'; }
  else{ authLabel.textContent='Đăng nhập'; authBtn.onclick=()=>showAuthModal('login'); authBtn.querySelector('i').className='fas fa-user'; }
}
function showError(el,msg){ el.textContent=msg; el.style.display='block'; }
function togglePw(id){ const input=document.getElementById(id); input.type=input.type==='password'?'text':'password'; }

// ===== ADMIN =====
function showAdminPanel(){ document.getElementById('adminOverlay').classList.add('active'); document.getElementById('adminPanel').classList.add('open'); if(isAdminLoggedIn) loadAdminData(); }
function closeAdminPanel(){
  document.getElementById('adminOverlay').classList.remove('active'); document.getElementById('adminPanel').classList.remove('open');
  const u=document.getElementById('adminUser'), p=document.getElementById('adminPass'), e=document.getElementById('adminError');
  if(u) u.value=''; if(p) p.value=''; if(e) e.style.display='none';
}
function adminLogin(){
  const userVal=document.getElementById('adminUser').value.trim(), passVal=document.getElementById('adminPass').value, errEl=document.getElementById('adminError');
  if(userVal==='admin'&&passVal==='admin123'){ isAdminLoggedIn=true; document.getElementById('adminLoginSection').style.display='none'; document.getElementById('adminDashboard').style.display='block'; errEl.style.display='none'; loadAdminData(); renderProducts(); renderFlashSale(); }
  else{ errEl.textContent='Tên đăng nhập hoặc mật khẩu không đúng'; errEl.style.display='block'; }
}
function adminLogout(){ isAdminLoggedIn=false; document.getElementById('adminLoginSection').style.display='block'; document.getElementById('adminDashboard').style.display='none'; renderProducts(); renderFlashSale(); showToast('Đã đăng xuất khỏi admin',''); }
function loadAdminData(){
  orders=JSON.parse(localStorage.getItem('orders')||'[]'); users=JSON.parse(localStorage.getItem('users')||'[]');
  const totalRevenue=orders.filter(o=>o.status==='done').reduce((s,o)=>s+o.total,0), pending=orders.filter(o=>o.status==='pending').length;
  document.getElementById('statOrders').textContent=orders.length; document.getElementById('statUsers').textContent=users.length; document.getElementById('statRevenue').textContent=formatPrice(totalRevenue); document.getElementById('statPending').textContent=pending;
  renderOrdersTable(orders); renderUsersTable(); renderProductImageManager(); renderStockManager();
}

// ===== ADMIN STOCK =====
function renderStockManager(){
  const stockBody=document.getElementById('stockTableBody'), noEl=document.getElementById('noStockResults');
  if(!stockBody) return;
  const query=(document.getElementById('stockSearchInput')?.value||'').toLowerCase(), filter=document.getElementById('stockFilterSelect')?.value||'all';
  const totalOut=PRODUCTS.filter(p=>getStockStatus(p.id)==='out').length, totalLow=PRODUCTS.filter(p=>getStockStatus(p.id)==='low').length, totalOk=PRODUCTS.filter(p=>getStockStatus(p.id)==='ok').length;
  const el=id=>document.getElementById(id);
  if(el('stockCountOut')) el('stockCountOut').textContent=totalOut; if(el('stockCountLow')) el('stockCountLow').textContent=totalLow; if(el('stockCountOk')) el('stockCountOk').textContent=totalOk;
  const filtered=PRODUCTS.filter(p=>{ const ms=!query||p.name.toLowerCase().includes(query); const mf=filter==='all'||getStockStatus(p.id)===filter; return ms&&mf; });
  if(!filtered.length){ stockBody.innerHTML=''; if(noEl) noEl.style.display='block'; return; }
  if(noEl) noEl.style.display='none';
  const catLabels={rau:'Rau củ','trai-cay':'Trái cây',thit:'Thịt','hai-san':'Hải sản','trung-sua':'Trứng & Sữa','ngu-coc':'Ngũ cốc','gia-vi':'Gia vị'};
  stockBody.innerHTML=filtered.map(p=>{ const qty=getStock(p.id), status=getStockStatus(p.id); const badgeHtml={out:`<span class="stock-status-badge badge-out"><i class="fas fa-times-circle"></i> Hết hàng</span>`,low:`<span class="stock-status-badge badge-low"><i class="fas fa-exclamation-triangle"></i> Sắp hết</span>`,ok:`<span class="stock-status-badge badge-ok"><i class="fas fa-check-circle"></i> Còn hàng</span>`}[status]; return `<tr class="stock-row ${status==='out'?'row-out':status==='low'?'row-low':''}"><td><div style="display:flex;align-items:center;gap:10px"><img src="${getProductImage(p.id)}" alt="" style="width:40px;height:40px;object-fit:cover;border-radius:8px;flex-shrink:0;background:#f3f4f6" onerror="this.style.display='none'"><div><div style="font-weight:600;font-size:13px;color:#111827">${p.name}</div><div style="font-size:11px;color:#9ca3af">ID: ${p.id} · ${catLabels[p.category]||p.category}</div></div></div></td><td style="font-size:12px;color:#6b7280">${p.origin}</td><td>${badgeHtml}</td><td><div class="stock-qty-control"><button class="stock-qty-btn" onclick="adminAdjustStock(${p.id},-1)">−</button><input type="number" min="0" value="${qty}" class="stock-qty-input" id="stockInput-${p.id}" onchange="adminSetStock(${p.id},this.value)" onclick="this.select()"/><button class="stock-qty-btn" onclick="adminAdjustStock(${p.id},1)">+</button></div></td><td><div style="display:flex;gap:6px;flex-wrap:wrap"><button class="stock-action-btn btn-restock" onclick="adminSetStock(${p.id},getStock(${p.id})+50)"><i class="fas fa-plus"></i> +50</button><button class="stock-action-btn btn-restock" onclick="adminSetStock(${p.id},100)"><i class="fas fa-boxes"></i> Đặt 100</button><button class="stock-action-btn btn-zero" onclick="adminSetStock(${p.id},0)"><i class="fas fa-ban"></i> Về 0</button></div></td></tr>`; }).join('');
}
function exportStockCSV(){
  const rows=[['ID','Tên sản phẩm','Danh mục','Xuất xứ','Giá','Tồn kho','Trạng thái']];
  PRODUCTS.forEach(p=>{ const status={out:'Hết hàng',low:'Sắp hết',ok:'Còn hàng'}[getStockStatus(p.id)]; rows.push([p.id,p.name,p.category,p.origin,p.price,getStock(p.id),status]); });
  const csv=rows.map(r=>r.map(c=>`"${c}"`).join(',')).join('\n'), blob=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8;'}), url=URL.createObjectURL(blob), a=document.createElement('a');
  a.href=url; a.download='tonkho_thucphamxanh.csv'; a.click(); URL.revokeObjectURL(url); showToast('Đã xuất file CSV tồn kho!','green');
}

// ===== ADMIN IMAGE MANAGER =====
function renderProductImageManager(){
  let section=document.getElementById('adminImageSection');
  if(!section){ section=document.createElement('div'); section.id='adminImageSection'; section.style.cssText='margin-top:28px'; section.innerHTML=`<h3 style="font-size:15px;font-weight:700;color:var(--dark);margin-bottom:6px"><i class="fas fa-images" style="color:var(--green);margin-right:6px"></i>Quản lý ảnh sản phẩm</h3><p style="font-size:12px;color:#999;margin-bottom:14px">Nhấn "Tải ảnh" để thay ảnh sản phẩm (tối đa 2MB/ảnh, lưu trên trình duyệt)</p><div id="adminImgGrid" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:12px"></div>`; const dash=document.getElementById('adminDashboard'); if(dash) dash.appendChild(section); }
  const custom=loadCustomImages(), grid=document.getElementById('adminImgGrid'); if(!grid) return;
  grid.innerHTML=PRODUCTS.map(p=>{ const imgSrc=getProductImage(p.id), hasCustom=!!custom[p.id]; return `<div style="border:1px solid #eee;border-radius:10px;overflow:hidden;background:#fff;box-shadow:0 1px 4px rgba(0,0,0,.06)"><div style="position:relative;height:110px;background:#f8f8f8"><img src="${imgSrc}" alt="${p.name}" style="width:100%;height:110px;object-fit:cover;display:block" onerror="this.src='data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 width=%22150%22 height=%22110%22%3E%3Crect fill=%22%23f0f0f0%22 width=%22150%22 height=%22110%22/%3E%3C/svg%3E'">${hasCustom?`<span style="position:absolute;top:5px;right:5px;background:var(--green);color:#fff;font-size:9px;padding:2px 5px;border-radius:4px;font-weight:600">Tuỳ chỉnh</span>`:''}</div><div style="padding:8px"><div style="font-size:11px;font-weight:600;color:#333;margin-bottom:6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="${p.name}">${p.name}</div><label style="display:flex;align-items:center;justify-content:center;gap:5px;cursor:pointer;background:var(--green);color:#fff;border-radius:6px;padding:5px;font-size:11px;font-weight:600"><i class="fas fa-upload"></i> Tải ảnh<input type="file" accept="image/*" style="display:none" onchange="handleProductImageUpload(${p.id},this.files[0])"></label>${hasCustom?`<button onclick="resetProductImage(${p.id})" style="margin-top:5px;width:100%;background:none;border:1px solid #ddd;border-radius:6px;padding:4px;font-size:11px;cursor:pointer;color:#888">↩ Mặc định</button>`:''}</div></div>`; }).join('');
}

// ===== ADMIN AVATAR (ẢNH ĐẠI DIỆN CỦA ADMIN) =====
// Avatar riêng cho tài khoản ADMIN (khác với avatar khách hàng ở _avatarKey()).
// HTML cần có trong khu vực header admin dashboard, ví dụ:
//   <div id="adminAvatarDisplay" class="admin-avatar"></div>
//   <label><input type="file" accept="image/*" style="display:none"
//          onchange="handleAdminAvatarUpload(this.files[0])">Đổi ảnh đại diện admin</label>
//   <button onclick="resetAdminAvatar()">↩ Về ảnh mặc định</button>

const ADMIN_AVATAR_KEY = 'tpx_admin_avatar';
// Ảnh mặc định của admin (đã resize 256x256 cho nhẹ)
const DEFAULT_ADMIN_AVATAR = 'data:image/jpeg;base64,';
const ADMIN_AVATAR_TARGET_IDS = ['adminAvatarDisplay'];

function getAdminAvatar(){
  try{ return localStorage.getItem(ADMIN_AVATAR_KEY) || DEFAULT_ADMIN_AVATAR; }
  catch(e){ return DEFAULT_ADMIN_AVATAR; }
}
function applyAdminAvatar(){
  const src=getAdminAvatar();
  ADMIN_AVATAR_TARGET_IDS.forEach(id=>{
    const el=document.getElementById(id);
    if(el) el.innerHTML=`<img src="${src}" alt="Admin avatar" style="width:100%;height:100%;object-fit:cover;border-radius:50%">`;
  });
}
function handleAdminAvatarUpload(file){
  if(!isAdminLoggedIn){ showToast('Chỉ admin mới có thể đổi ảnh đại diện!','red'); return; }
  if(!file||!file.type.startsWith('image/')){ showToast('Vui lòng chọn file ảnh hợp lệ','red'); return; }
  if(file.size>3*1024*1024){ showToast('Ảnh quá lớn, vui lòng chọn ảnh dưới 3MB','red'); return; }
  const reader=new FileReader();
  reader.onload=(e)=>{
    try{ localStorage.setItem(ADMIN_AVATAR_KEY,e.target.result); }
    catch(err){ showToast('Không thể lưu ảnh (dung lượng quá lớn)','red'); return; }
    applyAdminAvatar(); tpxBroadcast('admin_avatar',{}); showToast('Đã cập nhật ảnh đại diện admin!','green');
  };
  reader.readAsDataURL(file);
}
function resetAdminAvatar(){
  if(!isAdminLoggedIn) return;
  localStorage.removeItem(ADMIN_AVATAR_KEY);
  applyAdminAvatar(); tpxBroadcast('admin_avatar',{}); showToast('Đã khôi phục ảnh đại diện mặc định của admin','');
}
document.addEventListener('DOMContentLoaded', applyAdminAvatar);

// ===== ADMIN ORDERS =====
function renderOrdersTable(list){
  const tbody=document.getElementById('ordersTableBody'), noOrders=document.getElementById('noOrders');
  if(!list.length){ tbody.innerHTML=''; if(noOrders) noOrders.style.display='block'; return; }
  if(noOrders) noOrders.style.display='none';
  const statusMap={pending:'Chờ xử lý',processing:'Đang giao',done:'Hoàn thành',cancelled:'Đã hủy'}, statusClass={pending:'status-pending',processing:'status-processing',done:'status-done',cancelled:'status-cancelled'};
  tbody.innerHTML=list.slice().reverse().map(o=>{ const itemNames=o.items.map(i=>`${i.name} x${i.qty}`).join(', '); return `<tr><td><strong>${o.id}</strong></td><td><div style="font-weight:600">${o.userName}</div><div style="color:#999;font-size:11px">${o.userPhone||o.userId}</div></td><td style="max-width:180px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${itemNames}</td><td><strong style="color:var(--red)">${formatPrice(o.total)}</strong></td><td style="color:#999;font-size:12px">${o.time}</td><td><span class="status-badge ${statusClass[o.status]}">${statusMap[o.status]}</span></td><td><div class="admin-action-btns">${o.status==='pending'?`<button class="btn-status approve" onclick="updateOrderStatus('${o.id}','processing')">Duyệt</button>`:''}${o.status==='processing'?`<button class="btn-status approve" onclick="updateOrderStatus('${o.id}','done')">Hoàn thành</button>`:''}${o.status!=='done'&&o.status!=='cancelled'?`<button class="btn-status cancel" onclick="updateOrderStatus('${o.id}','cancelled')">Hủy</button>`:''}</div></td></tr>`; }).join('');
}

// ===== ADMIN USERS =====
function renderUsersTable(){
  const tbody=document.getElementById('usersTableBody');
  tbody.innerHTML=users.map((u,i)=>{ const userOrders=orders.filter(o=>o.userId===u.email), spent=userOrders.reduce((s,o)=>s+o.total,0), address=u.address?u.address:'<span style="color:#d1d5db;font-style:italic">Chưa cập nhật</span>', providerBadge=u.provider&&u.provider!=='local'?`<span style="display:inline-block;background:#e8f0fd;color:#1877f2;font-size:10px;font-weight:700;padding:1px 6px;border-radius:10px;margin-left:4px">${u.provider}</span>`:''; return `<tr><td style="font-size:13px;color:#6b7280">${i+1}</td><td><strong>${u.name}</strong>${providerBadge}</td><td style="font-size:12px">${u.email}</td><td style="font-size:13px">${u.phone||'<span style="color:#d1d5db;font-style:italic">—</span>'}</td><td style="font-size:13px;max-width:200px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="${u.address||''}">${address}</td><td><span class="status-badge status-processing">${userOrders.length} đơn</span></td><td><strong style="color:var(--green)">${formatPrice(spent)}</strong></td></tr>`; }).join('')||'<tr><td colspan="7" style="text-align:center;padding:24px;color:#999">Chưa có khách hàng</td></tr>';
}
function updateOrderStatus(id,status){
  const order=orders.find(o=>o.id===id); if(!order) return;
  order.status=status; localStorage.setItem('orders',JSON.stringify(orders));
  const labels={processing:'Đã duyệt đơn hàng',done:'Đơn hàng hoàn thành',cancelled:'Đã hủy đơn hàng'};
  tpxBroadcast('orders',{notifyCustomer:true,userId:order.userId,message:`Đơn hàng ${order.id}: ${labels[status]||status}`});
  loadAdminData(); showToast(labels[status]||'Cập nhật thành công','green');
}
function filterOrders(){ const val=document.getElementById('orderFilter').value, filtered=val==='all'?orders:orders.filter(o=>o.status===val); renderOrdersTable(filtered); }

// ===== COUNTDOWN =====
function startCountdown(){
  let total=5*3600+30*60; const elH=document.getElementById('hours'), elM=document.getElementById('minutes'), elS=document.getElementById('seconds');
  const tick=()=>{ if(elH) elH.textContent=String(Math.floor(total/3600)).padStart(2,'0'); if(elM) elM.textContent=String(Math.floor((total%3600)/60)).padStart(2,'0'); if(elS) elS.textContent=String(total%60).padStart(2,'0'); if(total--<=0) total=86399; };
  tick(); setInterval(tick,1000);
}

// ===== TOAST =====
function showToast(msg,type=''){ const t=document.getElementById('toast'); if(!t) return; t.textContent=msg; t.className=`toast ${type} show`; setTimeout(()=>t.className='toast',3200); }

// ===== UTILS =====
function formatPrice(n){ return n.toLocaleString('vi-VN')+'₫'; }

